import{_ as e,c as a,o as r,a4 as t}from"./chunks/framework.CRCV4hx_.js";const o="/statamic-partner.svg",g=JSON.parse('{"title":"Support & Pricing","description":"","frontmatter":{},"headers":[],"relativePath":"support.md","filePath":"support.md"}'),i={name:"support.md"},s=t('<h1 id="support-pricing" tabindex="-1">Support &amp; Pricing <a class="header-anchor" href="#support-pricing" aria-label="Permalink to &quot;Support &amp; Pricing&quot;">​</a></h1><p>Here you can find information about purchasing Resrv and getting support.</p><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Hello! I&#39;m Iosif, a web developer and designer from Kos, Greece. With 20 years of experience, I&#39;ve journeyed through various technologies, from Wordpress &amp; Joomla to discovering the rad path of web creation. Yes, I&#39;m talking about Statamic!</p><p>In 2012, I founded <strong>Reach Web Agency</strong>, and since then, I&#39;ve worked with numerous coders and designers. We&#39;ve been exclusively using Statamic since 2020, and our clients love it! As the primary developer in our team, I&#39;ve created several Statamic add-ons, which you can find on our <a href="https://statamic.com/sellers/reach" target="_blank" rel="noreferrer">store page</a>.</p><p>I&#39;m also part of the Statamic Certified Partners Program and I&#39;m regularly active in the Statamic community.</p><a href="https://statamic.com/partners/iosif-chatzimichail" target="_blank"><img src="'+o+'" alt="Statamic partner logo" width="200"></a><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>I&#39;m always happy to assist with any issues you encounter. However, please note that Resrv is provided as-is, and I can&#39;t guarantee immediate support for urgent issues.</p><p>If you need help with Resrv, you can reach out to me:</p><ul><li><strong>Open an issue on GitHub</strong>: If you find a problem with the addon or have a feature request, submit an issue on the <a href="https://github.com/reachweb/statamic-resrv/issues" target="_blank" rel="noreferrer">Resrv GitHub repository</a>.</li><li><strong>Email</strong>: Feel free to email me at <a href="mailto:info@reach.gr" target="_blank" rel="noreferrer">info@reach.gr</a>. I typically respond within a day or two.</li></ul><p>Don&#39;t hesitate to get in touch! I really enjoy learning how people use Resrv and I&#39;m always happy to help.</p><h2 id="paid-support" tabindex="-1">Paid Support <a class="header-anchor" href="#paid-support" aria-label="Permalink to &quot;Paid Support&quot;">​</a></h2><p>If you need dedicated support for Resrv or help with Statamic, Laravel, or Livewire, I can assist you. Contact me for an estimate. As a registered EU business, I can provide invoicing for any services.</p><h2 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h2><p>Resrv is not free. You can use it for free during development, but you&#39;ll need to <a href="https://statamic.com/addons/reach/resrv" target="_blank" rel="noreferrer">purchase a license</a> before going live.</p><p>Given the work that&#39;s gone into it and the types of websites it&#39;s designed for, I believe the price is fair. However, if you&#39;re unable to afford it or are using Resrv for a non-profit or open-source project, feel free to reach out to me.</p>',17),n=[s];function p(c,u,l,h,d,m){return r(),a("div",null,n)}const v=e(i,[["render",p]]);export{g as __pageData,v as default};
